import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.z3u3TMv0.js";const g=JSON.parse('{"title":"ComfyUI installieren","description":"ComfyUI mit LAN-Listen für MiniTavern-Bildverbindung und Default-Workflow.","frontmatter":{"title":"ComfyUI installieren","description":"ComfyUI mit LAN-Listen für MiniTavern-Bildverbindung und Default-Workflow.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"ComfyUI installieren · MiniTavern Docs"}],["meta",{"property":"og:description","content":"ComfyUI mit LAN-Listen für MiniTavern-Bildverbindung und Default-Workflow."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/local/image-gen/comfyui"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/local/image-gen/comfyui"}]]},"headers":[],"relativePath":"de/local/image-gen/comfyui.md","filePath":"de/local/image-gen/comfyui.md","lastUpdated":1787224147000}'),s={name:"de/local/image-gen/comfyui.md"};function l(r,e,o,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="comfyui-installieren" tabindex="-1">ComfyUI installieren <a class="header-anchor" href="#comfyui-installieren" aria-label="Permalink to &quot;ComfyUI installieren&quot;">​</a></h1><p>ComfyUI ist ein node-basiertes lokales Bild-Frontend mit schneller Unterstützung neuer Modelle.<br> MiniTavern sendet über die HTTP-API (<code>/prompt</code> usw.) einen <strong>eingebauten Default-Workflow</strong> — ohne Node-Graph in der App.</p><p>Docs: <a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">docs.comfy.org</a> · Repo: <a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">Comfy-Org/ComfyUI</a></p><h2 id="hardware" tabindex="-1">Hardware <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;Hardware&quot;">​</a></h2><table tabindex="0"><thead><tr><th>VRAM</th><th>Empfehlung</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5 und kleinere Workflows</td></tr><tr><td>8–12GB</td><td>SDXL, manche schnelle Flux-Varianten realistischer</td></tr><tr><td>Apple Silicon</td><td>nativ möglich, meist langsamer als vergleichbare NVIDIA</td></tr></tbody></table><h2 id="weg-a-windows-portable-empfohlen" tabindex="-1">Weg A: Windows Portable (empfohlen) <a class="header-anchor" href="#weg-a-windows-portable-empfohlen" aria-label="Permalink to &quot;Weg A: Windows Portable (empfohlen)&quot;">​</a></h2><ol><li><a href="https://www.comfy.org/download" target="_blank" rel="noreferrer">ComfyUI Download</a> (oder Community-<code>ComfyUI_windows_portable</code>).</li><li>Entpacken (kurzer Pfad, möglichst ohne chinesische Leerzeichen).</li><li>NVIDIA: <code>run_nvidia_gpu.bat</code>; CPU: entsprechendes Script.</li><li>Browser laut Hinweis, oft:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><h2 id="weg-b-desktop-app" tabindex="-1">Weg B: Desktop-App <a class="header-anchor" href="#weg-b-desktop-app" aria-label="Permalink to &quot;Weg B: Desktop-App&quot;">​</a></h2><ol><li><a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">ComfyUI Desktop</a> installieren.</li><li>Einstellungen → Server Configuration (o. ä.): <ul><li><strong>Listen Address</strong> → <code>0.0.0.0</code> (Default <code>127.0.0.1</code> blockiert Handys)</li><li><strong>Port</strong> notieren (Desktop oft <strong>8000</strong>, Portable 8188)</li></ul></li><li>Neu starten, dann LAN-IP nutzen.</li></ol><h2 id="weg-c-git-macos-linux-fortgeschritten" tabindex="-1">Weg C: Git (macOS / Linux / fortgeschritten) <a class="header-anchor" href="#weg-c-git-macos-linux-fortgeschritten" aria-label="Permalink to &quot;Weg C: Git (macOS / Linux / fortgeschritten)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Comfy-Org/ComfyUI.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ComfyUI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows: venv\\Scripts\\activate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># passendes PyTorch laut PyTorch-Website</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span></span></code></pre></div><h2 id="lan-furs-handy-pflicht" tabindex="-1">LAN (fürs Handy Pflicht) <a class="header-anchor" href="#lan-furs-handy-pflicht" aria-label="Permalink to &quot;LAN (fürs Handy Pflicht)&quot;">​</a></h2><h3 id="portable-cli" tabindex="-1">Portable / CLI <a class="header-anchor" href="#portable-cli" aria-label="Permalink to &quot;Portable / CLI&quot;">​</a></h3><p>In Startscript (z. B. <code>run_nvidia_gpu.bat</code>) nach <code>main.py</code>:</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--listen</span></span></code></pre></div><p>Beispiel:</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\python_embeded\\python.exe -s ComfyUI\\main.py --windows-standalone-build --listen</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Wirkung</th></tr></thead><tbody><tr><td><code>--listen</code></td><td>alle Interfaces, LAN erlaubt</td></tr><tr><td><code>--port 8188</code></td><td>optional</td></tr><tr><td><code>--enable-cors-header</code></td><td>nur bei Browser-CORS; native App meist unnötig</td></tr></tbody></table><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>Wie oben: Listen <code>0.0.0.0</code>, Port laut UI.</p><h2 id="modelle-ablegen" tabindex="-1">Modelle ablegen <a class="header-anchor" href="#modelle-ablegen" aria-label="Permalink to &quot;Modelle ablegen&quot;">​</a></h2><p>Checkpoints (<code>.safetensors</code>) nach:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComfyUI/models/checkpoints/</span></span></code></pre></div><p>Mit <code>R</code> Liste aktualisieren oder neu starten. Zuerst manuell Default-Text-to-Image in der Web-UI, dann App.</p><p>Quellen: <a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> · <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a>.</p><h2 id="prufen" tabindex="-1">Prüfen <a class="header-anchor" href="#prufen" aria-label="Permalink to &quot;Prüfen&quot;">​</a></h2><p>Lokal:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><p>LAN (Desktop: Port beachten):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:8188</span></span></code></pre></div><p>Handy-Browser öffnet dieselbe Adresse → Netz und Listen ok.</p><h2 id="unterschiede-zu-minitavern-vorher-lesen" tabindex="-1">Unterschiede zu MiniTavern (vorher lesen) <a class="header-anchor" href="#unterschiede-zu-minitavern-vorher-lesen" aria-label="Permalink to &quot;Unterschiede zu MiniTavern (vorher lesen)&quot;">​</a></h2><ul><li>App nutzt <strong>eingebauten Default-Workflow</strong> und wählt meist verfügbare Checkpoints; komplexe Custom-Graphs serverseitig, außerhalb dieses Tutorials.</li><li>Default-Comfy <strong>ohne Referenzbilder</strong> (Referenz erzeugt keinen Fehler); Face-Lock → <a href="/ultra_guides/de/local/image-gen/a1111">A1111</a> oder Cloud mit Referenz.</li><li>Schlaf/Deckel stoppt den Dienst; IP-Wechsel → Base URL in der App aktualisieren.</li></ul><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/ultra_guides/de/local/image-gen/connect-app">In MiniTavern konfigurieren</a></li><li>Übersicht: <a href="/ultra_guides/de/local/image-gen/">Bildmodelle lokal</a></li></ul>`,36)])])}const u=a(s,[["render",l]]);export{g as __pageData,u as default};
